using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class KeyframeEditorOperations
{
    public void number(Control owner,string label,double value,Variant callback)=>Number(owner,label,value,n=>owner.Call("_invoke_number_changes",callback,n).AsGodotDictionary());
    private void Number(Control owner,string label,double value,Func<double,Settings> changes)
    {
        var box=new HBoxContainer();Details(owner).AddChild(box);var title=new Label{Text=label=="Time (s)"?"Time":label=="Attenuation"?"Ease":label,TooltipText=label};title.AddThemeFontSizeOverride("font_size",10);box.AddChild(title);var input=NewNumber();input.AllowGreater=true;input.AllowLesser=true;input.Step=.01;input.CustomMinimumSize=new Vector2(68,0);input.SetValueNoSignal(value);box.AddChild(input);var selected=Selected(owner);if(selected.Count==0)return;string id=selected[selected.Count-1].AsString();int axis=Array.IndexOf(new[]{"X","Y","Z","W"},label);Updaters(owner).Add(Callable.From(()=>{var actor=Actor(owner);var current=actor!=null?_timeline.keyframe_for_id(actor,id):null;if(current==null)return;double sampled;if(label=="Time (s)"){var clip=_timeline.clip_for_actor_id(Model(owner),actor!.Get("id").AsString());if(clip==null)return;sampled=clip.Get("start_time").AsDouble()+(current.Get("time").AsDouble()-clip.Get("source_offset").AsDouble())/clip.Get("playback_speed").AsDouble();}else if(label=="Attenuation")sampled=current.Get("attenuation").AsDouble();else if(label=="Value")sampled=current.Get("value").AsDouble();else sampled=ActorAnimationOperations.Component(current.Get("value"),axis).AsDouble();input.SetValueNoSignal(sampled);}));input.Connect("interaction_started",Callable.From(()=>{begin_edit(owner);Hint(owner,input,"Esc cancels keyframe property drag");}));input.Connect("preview_changed",Callable.From<double>(n=>change_keys(owner,id,changes(n),true,axis)));input.Connect("drag_committed",Callable.From<double>(_=>finish_edit(owner)));input.Connect("drag_cancelled",Callable.From(()=>cancel_edit(owner)));input.ValueChanged+=n=>change_keys(owner,id,changes(n),false,axis);input.Connect("interaction_ended",Callable.From(()=>Hint(owner,input,"")));
    }
    public void build_details(Control owner)
    {
        var actor=Actor(owner);var selected=Selected(owner);string id=selected.Count>0?selected[selected.Count-1].AsString():"";var track=actor!=null?_timeline.track_for_key(actor,id):null;string signature=(actor?.Get("id").AsString()??"")+"|"+id+"|"+(track?.Get("component").AsInt32()??-1);if(actor!=null&&actor.Get("type_id").AsString()=="transform_image_2d"){var asset=Asset(actor);var document=asset["document"].As<Resource>();signature+="|"+(document!=null?document.GetInstanceId().ToString():asset["error"].ToString());}var details=Details(owner);if(signature==owner.Get("_details_signature").AsString()&&details.GetChildCount()>0){if(!owner.Get("_editing").AsBool())owner.Call("_run_detail_updaters");return;}owner.Set("_details_signature",signature);Updaters(owner).Clear();foreach(var child in details.GetChildren()){details.RemoveChild(child);child.QueueFree();}if(actor==null||selected.Count==0){details.AddChild(new Label{Text=actor==null||actor.Get("animation_tracks").AsGodotArray().Count==0?"Select an actor and add keys using property diamonds.":"Click a key to edit it. Shift-click to move multiple keys.",AutowrapMode=TextServer.AutowrapMode.Off,CustomMinimumSize=new Vector2(240,0),Modulate=new Color("819db4")});owner.CallDeferred("_layout_editor");return;}var key=_timeline.keyframe_for_id(actor,id);var clip=_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString());if(key==null||clip==null||track==null)return;Number(owner,"Time (s)",clip.Get("start_time").AsDouble()+(key.Get("time").AsDouble()-clip.Get("source_offset").AsDouble())/clip.Get("playback_speed").AsDouble(),n=>new Settings{["time"]=_clips.local_time(clip,n)});add_curve_button(owner,key);bool separate=track.Get("component").AsInt32()>=0;if(separate||_timeline.component_count(key.Get("value"))>0){var button=new Button{Text=separate?"Unseparate":"Separate",TooltipText=separate?"Join components at their combined key times":"Give each component its own independently editable track"};details.AddChild(button);button.Pressed+=()=>{if(separate)_timeline.unseparate_track(Model(owner),actor,track.Get("path").AsStringArray());else _timeline.separate_track(Model(owner),actor,track.Get("path").AsStringArray());};}
        var value=key.Get("value");switch(value.VariantType){case Variant.Type.Int:case Variant.Type.Float:Number(owner,"Value",value.AsDouble(),n=>new Settings{["value"]=value.VariantType==Variant.Type.Int?Variant.From((long)Math.Round(n,MidpointRounding.AwayFromZero)):Variant.From(n)});break;
        case Variant.Type.Vector2:case Variant.Type.Vector3:case Variant.Type.Vector4:case Variant.Type.Vector2I:case Variant.Type.Vector3I:case Variant.Type.Vector4I:for(int i=0;i<_timeline.component_count(value);i++){int axis=i;Number(owner,new[]{"X","Y","Z","W"}[axis],ActorAnimationOperations.Component(value,axis).AsDouble(),n=>{var current=_timeline.keyframe_for_id(actor,id);var vector=current!=null?current.Get("value"):value;bool integer=vector.VariantType is Variant.Type.Vector2I or Variant.Type.Vector3I or Variant.Type.Vector4I;return new Settings{["value"]=ActorAnimationOperations.WithComponent(vector,axis,integer?Variant.From((long)Math.Round(n,MidpointRounding.AwayFromZero)):Variant.From(n))};});}break;
        case Variant.Type.Bool:var toggle=new CheckButton{Text="Value",ButtonPressed=value.AsBool()};details.AddChild(toggle);toggle.Toggled+=n=>change_keys(owner,id,new Settings{["value"]=n},false,-1);Updaters(owner).Add(Callable.From(()=>{var current=_timeline.keyframe_for_id(actor,id);if(current!=null)toggle.SetPressedNoSignal(current.Get("value").AsBool());}));break;
        case Variant.Type.String:case Variant.Type.StringName:if(_tracks.is_state_track(track)&&actor.Get("type_id").AsString()=="transform_image_2d")add_state_value(owner,track,key);else{var text=new LineEdit{Text=value.ToString(),CustomMinimumSize=new Vector2(180,0)};details.AddChild(text);text.TextSubmitted+=n=>change_keys(owner,id,new Settings{["value"]=value.VariantType==Variant.Type.StringName?Variant.From(new StringName(n)):Variant.From(n)},false,-1);Updaters(owner).Add(Callable.From(()=>{var current=_timeline.keyframe_for_id(actor,id);if(current!=null&&!text.HasFocus())text.Text=current.Get("value").ToString();}));}break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Color=value.AsColor();details.AddChild(color);color.Connect("interaction_started",Callable.From(()=>{begin_edit(owner);Hint(owner,color,"Esc cancels keyframe color drag");}));color.Connect("preview_changed",Callable.From<Color>(n=>change_keys(owner,id,new Settings{["value"]=n},true,-1)));color.Connect("drag_committed",Callable.From<Color,Color>((_,_)=>finish_edit(owner)));color.Connect("drag_cancelled",Callable.From<Color>(_=>cancel_edit(owner)));color.Connect("interaction_ended",Callable.From(()=>Hint(owner,color,"")));Updaters(owner).Add(Callable.From(()=>{var current=_timeline.keyframe_for_id(actor,id);if(current!=null)color.Call("set_color_silent",current.Get("value"));}));break;}
        var remove=new Button{Text="Delete",TooltipText="Delete selected keyframes"};details.AddChild(remove);remove.Pressed+=()=>_timeline.delete_keyframes(Model(owner),actor,Selected(owner).Duplicate());layout_editor(owner);owner.CallDeferred("_layout_editor");
    }
}
